draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // character
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // doubt cloud
  ctx.beginPath();
  ctx.arc(W/2 + 30 + 10 * Math.sin(t), H/2 - 20 + 10 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.stroke();

  // success trophy
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 - 20);
  ctx.lineTo(W/2 - 30, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2);
  ctx.closePath();
  ctx.stroke();

  // doubt lines
  ctx.beginPath();
  ctx.moveTo(W/2 + 30 + 10 * Math.sin(t), H/2 - 20 + 10 * Math.cos(t));
  ctx.lineTo(W/2 - 30, H/2 - 20);
  ctx.stroke();

  // imposter mask
  ctx.beginPath();
  ctx.arc(W/2, H/2, 15, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
